// Fictional schematic city. Routes use the visible street graph, not live map data.
function cityMapRuntime(){
 const names=['North Park','Gallery','North Bridge','Lookout','Library','Central Station','Market','Museum','Garden','Cafe','Riverside','Arcade'];
 const nodes=names.map((name,i)=>({name,x:65+(i%4)*140,y:45+Math.floor(i/4)*100}));
 let destination=6,closed=false;
 const svg=document.querySelector('svg'),result=document.querySelector('#route-result'),budget=document.querySelector('#walk-budget');
 function renderMap(){
  const edges=[];nodes.forEach((n,i)=>{if(i%4<3&&!(i===9)&&!(closed&&i===5))edges.push([i,i+1,4]);if(i<8)edges.push([i,i+4,3])});
  const distance=Array(12).fill(Infinity),previous=Array(12).fill(null),visited=new Set();distance[5]=0;
  for(let step=0;step<12;step++){let at=-1;for(let i=0;i<12;i++)if(!visited.has(i)&&(at===-1||distance[i]<distance[at]))at=i;if(at===-1||!Number.isFinite(distance[at]))break;visited.add(at);for(const [a,b,cost] of edges){const next=a===at?b:b===at?a:-1;if(next>=0&&distance[at]+cost<distance[next]){distance[next]=distance[at]+cost;previous[next]=at}}}
  const route=[];for(let at=destination;at!==null;at=previous[at])route.unshift(at);
  const path=route.map(i=>`${nodes[i].x},${nodes[i].y}`).join(' ');
  svg.innerHTML=`<path d="M277 0 Q250 80 279 145 T278 300" fill="none" stroke="#244c56" stroke-width="34"/><rect x="12" y="10" width="108" height="67" rx="18" fill="#243c25"/><rect x="11" y="208" width="110" height="75" rx="18" fill="#243c25"/>${edges.map(([a,b])=>`<line x1="${nodes[a].x}" y1="${nodes[a].y}" x2="${nodes[b].x}" y2="${nodes[b].y}" stroke="#52665a" stroke-width="7"/>`).join('')}<polyline points="${path}" fill="none" stroke="#c6ff3a" stroke-width="5" stroke-linejoin="round"/>${closed?'<text x="275" y="136" text-anchor="middle" fill="#ff9b8b" font-size="12">BRIDGE CLOSED</text>':''}${nodes.map((n,i)=>`<g data-node="${i}" role="button" tabindex="0" aria-label="Route to ${n.name}" aria-pressed="${destination===i}"><circle cx="${n.x}" cy="${n.y}" r="19" fill="transparent"/><circle cx="${n.x}" cy="${n.y}" r="${i===5?9:7}" fill="${i===5||i===destination?'#c6ff3a':distance[i]<=+budget.value?'#86b75c':'#18271f'}" stroke="${i===destination?'#fff':'#aac7b3'}" stroke-width="2"/><text x="${n.x}" y="${n.y+29}" text-anchor="middle" fill="#e0eae1" font-size="11">${n.name}</text></g>`).join('')}`;
  document.querySelector('#budget-value').textContent=budget.value+' min';
  result.textContent=destination===5?'Central Station · Your starting point':`${nodes[destination].name} · ${distance[destination]} min walk · ${distance[destination]<=+budget.value?'Within your budget':'Over your budget'}`;
  document.querySelector('#reachable').textContent=distance.filter((d,i)=>i!==5&&d<=+budget.value).length+' places within reach';
 }
 function select(e){const marker=e.target.closest('[data-node]');if(!marker)return;destination=+marker.dataset.node;renderMap();svg.querySelector(`[data-node="${destination}"]`).focus()}
 svg.addEventListener('click',select);svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(e)}});
 budget.addEventListener('input',renderMap);
 document.querySelector('#bridge-toggle').addEventListener('change',e=>{closed=e.target.checked;renderMap()});
 document.querySelector('#map-reset').addEventListener('click',()=>{destination=6;closed=false;budget.value=10;document.querySelector('#bridge-toggle').checked=false;renderMap()});
 renderMap();
}
const cityMapHtml=`<!doctype html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;padding:30px 14px 14px;background:#101b16;color:#e5eee7;font:12px system-ui;display:flex;flex-direction:column;height:100vh;gap:9px}header{display:flex;justify-content:space-between;gap:8px;font:10px ui-monospace,monospace;letter-spacing:1px;color:#bbda9d}svg{display:block;flex:1;min-height:120px;width:100%;background:#13221a;border:1px solid #31493a;border-radius:6px}svg g{cursor:pointer;outline:none}svg g:focus circle:last-of-type{stroke:white;stroke-width:4}label{display:flex;align-items:center;gap:7px}input[type=range]{flex:1;min-width:30px;accent-color:#c6ff3a}input[type=checkbox]{accent-color:#c6ff3a}.controls{display:flex;align-items:center;justify-content:space-between;gap:8px}button{background:#253922;color:#e5eee7;border:1px solid #4b643e;border-radius:4px;padding:5px 9px;cursor:pointer;font:inherit}button:focus-visible,input:focus-visible{outline:2px solid #c6ff3a}p{margin:0;line-height:1.45}#route-result{color:#c6ff3a;font-weight:600;min-height:17px}.note{font-size:10px;color:#a1b7a8}.budget{white-space:nowrap}output{min-width:42px}</style><body><header><span>THE WALKABLE CITY</span><span id="reachable"></span></header><svg viewBox="0 0 550 300" aria-label="Interactive fictional city map. Choose a destination." role="group"></svg><p id="route-result" role="status" aria-live="polite"></p><label class="budget">Walking budget <input id="walk-budget" aria-label="Walking budget in minutes" type="range" min="3" max="20" value="10"><output id="budget-value">10 min</output></label><div class="controls"><label><input id="bridge-toggle" type="checkbox">Close central bridge</label><button id="map-reset">Reset</button></div><p class="note">Tap a place to plan a route from Central Station. Fictional map; illustrative walking times.</p><script>(${cityMapRuntime.toString()})();<\/script></body></html>`;
const cityMapWork={id:'walkable-city',contentType:'interactive',assetType:'html',asset:cityMapHtml,template:'orbit',cat:'Simulation',title:'How far can you walk in 10 minutes?',desc:'Explore an interactive city map. Pick a destination, adjust your walking budget, and close a bridge to see your route change.',author:'Atlas Lab',time:'Interactive map · 2 min',likes:0,plays:'0',bg:'#13221a'};
works.unshift(cityMapWork);render();
if(location.hash==='#work=walkable-city')openWork('walkable-city');
